//! The types every typed AST generated by `ts-bnf-tool scaffold --ast-types
//! --partial-trees` has in common, in one crate rather than one private copy
//! in each generated crate.
//!
//! That is the point of this crate: with a copy per generated crate, the trees
//! of two languages have unrelated `Reflect` and `Span` types, and code that
//! handles several languages needs a conversion for each. With one crate they
//! share the types, so code written against `&dyn` [`Reflect`] — a serializer,
//! a linter's front end — works for the typed tree of any of them:
//!
//! ```
//! use ts_bnf_runtime::{Reflect, walk};
//!
//! /// How many nodes a tree has, whichever language it is a tree of.
//! fn size(root: &dyn Reflect) -> usize {
//!     walk(root).count()
//! }
//! ```
//!
//! What is here has nothing to do with tree-sitter, and the crate has no
//! dependencies: the code that builds a typed tree from a tree-sitter one is
//! generated into each crate, which depends on this one and re-exports these
//! items from its `ast::runtime` module, so `my_lang::ast::runtime::Span` and
//! `ts_bnf_runtime::Span` are the same type.
//!
//! - Where a node is: [`Pragma`], [`Span`], [`Token`], [`ErrorRegion`].
//! - What went wrong, and the result of recovering from it: [`Diagnostic`],
//!   [`DiagnosticKind`], [`Recovered`], [`DEFAULT_MAX_DEPTH`].
//! - A view of any node, and a traversal of it: [`Reflect`], [`walk`],
//!   [`Walk`], [`Visit`].

mod recovery;
mod reflect;
mod span;

pub use recovery::{DEFAULT_MAX_DEPTH, Diagnostic, DiagnosticKind, Recovered};
pub use reflect::{Reflect, Visit, Walk, walk};
pub use span::{ErrorRegion, Pragma, Span, Token};
